element.style.fontFamily = 'sans-serif';

// Create the comparison matrix container
var matrixContainer = document.createElement('div');
matrixContainer.id = 'specs-comparison-matrix-container';
matrixContainer.style.cssText = 'position:fixed;top:80px;right:20px;z-index:9999;width:380px;max-height:80vh;background:#fff;border-radius:12px;box-shadow:0 4px 24px rgba(0,0,0,0.15);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;overflow:hidden;transition:all 0.3s ease;border:1px solid #e0e0e0;';

// Header with toggle
var header = document.createElement('div');
header.style.cssText = 'background:linear-gradient(135deg,#1428a0 0%,#0a1a6b 100%);color:#fff;padding:16px 20px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;user-select:none;';
header.innerHTML = '<div style="display:flex;align-items:center;gap:10px;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16M4 12h16M4 18h16"/></svg><span style="font-weight:600;font-size:15px;">Compare Detailed Specifications</span></div><svg id="matrix-toggle-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="transition:transform 0.3s ease;"><path d="M6 9l6 6 6-6"/></svg>';

// Content area
var content = document.createElement('div');
content.id = 'specs-matrix-content';
content.style.cssText = 'max-height:0;overflow:hidden;transition:max-height 0.4s ease;';

// Specs table
var tableWrap = document.createElement('div');
tableWrap.style.cssText = 'padding:16px;overflow-y:auto;max-height:calc(80vh - 70px);';

var specsTable = document.createElement('table');
specsTable.style.cssText = 'width:100%;border-collapse:collapse;font-size:13px;';

// Table header
var thead = document.createElement('thead');
thead.innerHTML = '<tr><th style="text-align:left;padding:10px 8px;border-bottom:2px solid #1428a0;color:#1428a0;font-weight:600;width:40%;background:#f5f7ff;">Specification</th><th style="text-align:center;padding:10px 8px;border-bottom:2px solid #1428a0;color:#fff;background:#1428a0;font-weight:600;width:30%;">Config A</th><th style="text-align:center;padding:10px 8px;border-bottom:2px solid #e91e63;color:#fff;background:#e91e63;font-weight:600;width:30%;">Config B</th></tr>';

// Specs data rows
var specsData = [
  ['Processor', 'Intel Core i7-13700H', 'Intel Core i5-13500H'],
  ['Cores / Threads', '14 Cores / 20 Threads', '12 Cores / 16 Threads'],
  ['Base Clock', '2.4 GHz', '2.6 GHz'],
  ['Max Turbo', '5.0 GHz', '4.7 GHz'],
  ['RAM', '32GB DDR5-4800', '16GB DDR5-4800'],
  ['Storage', '1TB NVMe PCIe 4.0 SSD', '512GB NVMe PCIe 4.0 SSD'],
  ['Display Size', '15.6" FHD+', '15.6" FHD+'],
  ['Refresh Rate', '165Hz', '144Hz'],
  ['GPU', 'NVIDIA RTX 4070 8GB', 'NVIDIA RTX 4060 8GB'],
  ['GPU Boost Clock', '2475 MHz', '2460 MHz'],
  ['Battery', '90Wh Li-Polymer', '90Wh Li-Polymer'],
  ['Weight', '2.3 kg', '2.3 kg'],
  ['Wi-Fi', 'Wi-Fi 6E (802.11ax)', 'Wi-Fi 6E (802.11ax)'],
  ['Bluetooth', '5.3', '5.3'],
  ['Ports - USB-C', '2x Thunderbolt 4', '1x USB-C 3.2 + 1x TB4'],
  ['Ports - USB-A', '2x USB 3.2 Gen 1', '2x USB 3.2 Gen 1'],
  ['HDMI', 'HDMI 2.1', 'HDMI 2.1'],
  ['Webcam', '1080p FHD IR', '720p HD'],
  ['Audio', 'Dolby Atmos, 2x 2W speakers', 'Stereo, 2x 2W speakers'],
  ['Keyboard', 'RGB Backlit', 'White Backlit'],
  ['Fingerprint Reader', 'Yes (Power Button)', 'Yes (Touchpad)'],
  ['Operating System', 'Windows 11 Pro', 'Windows 11 Home'],
  ['Warranty', '2 Years Premium Support', '1 Year Standard'],
];

var tbody = document.createElement('tbody');
specsData.forEach(function(row, idx) {
  var tr = document.createElement('tr');
  if (idx % 2 === 0) {
    tr.style.background = '#fafbfc';
  }
  tr.innerHTML = '<td style="padding:9px 8px;border-bottom:1px solid #eee;font-weight:500;color:#333;">' + row[0] + '</td><td style="padding:9px 8px;border-bottom:1px solid #eee;text-align:center;color:#555;">' + row[1] + '</td><td style="padding:9px 8px;border-bottom:1px solid #eee;text-align:center;color:#555;">' + row[2] + '</td>';
  tbody.appendChild(tr);
});

// Benchmark section
var benchHeader = document.createElement('div');
benchHeader.style.cssText = 'margin-top:16px;padding:12px;background:#f0f4ff;border-radius:8px;font-weight:600;color:#1428a0;font-size:13px;display:flex;align-items:center;gap:8px;';
benchHeader.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#1428a0" stroke-width="2"><path d="M13 2L3 14h9l-1 10 10-12h-9l1-10z"/></svg>Benchmark Scores';

var benchTable = document.createElement('table');
benchTable.style.cssText = 'width:100%;border-collapse:collapse;font-size:13px;margin-top:8px;';
var benchData = [
  ['Cinebench R23 Multi', '16,850 pts', '13,240 pts'],
  ['Cinebench R23 Single', '1,890 pts', '1,720 pts'],
  ['3DMark Time Spy GPU', '10,200 pts', '8,650 pts'],
  ['PCMark 10 Overall', '8,920 pts', '8,100 pts'],
  ['Geekbench 6 Multi', '11,450 pts', '9,870 pts'],
  ['Blender BMW Scene', '4:32 min', '5:48 min'],
];

var benchTbody = document.createElement('tbody');
benchData.forEach(function(row) {
  var tr = document.createElement('tr');
  tr.style.background = '#fff';
  tr.innerHTML = '<td style="padding:7px 8px;border-bottom:1px solid #eee;font-weight:500;color:#333;">' + row[0] + '</td><td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:center;color:#1428a0;font-weight:600;">' + row[1] + '</td><td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:center;color:#e91e63;font-weight:600;">' + row[2] + '</td>';
  benchTbody.appendChild(tr);
});
benchTable.appendChild(benchTbody);

// Disclaimer
var disclaimer = document.createElement('div');
disclaimer.style.cssText = 'margin-top:16px;padding:10px;background:#fff8e1;border-radius:6px;font-size:11px;color:#7a6b00;line-height:1.5;';
disclaimer.innerHTML = '<strong>Note:</strong> These are representative specification comparisons. Actual values may vary based on specific model and configuration selected. Click to expand/collapse.';

// Assemble
tableWrap.appendChild(specsTable);
specsTable.appendChild(thead);
specsTable.appendChild(tbody);
tableWrap.appendChild(benchHeader);
tableWrap.appendChild(benchTable);
tableWrap.appendChild(disclaimer);
content.appendChild(tableWrap);

matrixContainer.appendChild(header);
matrixContainer.appendChild(content);

// Toggle logic
var isExpanded = true;
header.addEventListener('click', function() {
  isExpanded = !isExpanded;
  if (isExpanded) {
    content.style.maxHeight = 'calc(80vh - 70px)';
    document.getElementById('matrix-toggle-icon').style.transform = 'rotate(0deg)';
  } else {
    content.style.maxHeight = '0';
    document.getElementById('matrix-toggle-icon').style.transform = 'rotate(-90deg)';
  }
});

// Set initial state
content.style.maxHeight = 'calc(80vh - 70px)';

element.appendChild(matrixContainer);
